// Display the last committed attribution snapshot; never use GET, cache or collector-observation time.
function crmStamp(value){const n=Date.parse(value||'');return Number.isFinite(n)?n:0;}
function crmSendDay(value){if(!crmStamp(value))return '';const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value)).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day;}
function crmSendInRange(value,range){const day=crmSendDay(value);return !!range&&!!day&&day>=range.ini&&day<=range.fim;}
function crmRevenueUpdated(id,data,brand=crmState.brand,reason='Snapshot de receita não confirmado nesta consulta.'){
 const chip=crmEl(id);if(!chip)return;
 const now=Date.now(),valid=value=>typeof value==='string'&&Number.isFinite(Date.parse(value))&&Date.parse(value)<=now,Home=window.ShrigmaCrmHome,a=data?.crm_attribution;
 const marked=row=>{const values=['marca','brand'].filter(key=>Object.hasOwn(row||{},key)).map(key=>({fishermans:'fish',aristocrata:'aristo'}[row[key]]||row[key]));return values.length&&values.every(value=>value===brand);};
 const scoped=['fish','aristo'].includes(brand)&&data?.brand===brand&&JSON.stringify(data?.brands)===JSON.stringify([brand]);
 const confirmed=scoped&&a?.schema_version===2&&typeof Home?.validAttributionRow==='function'&&Array.isArray(a.daily)&&a.daily.every(row=>marked(row)&&Home.validAttributionRow(row))&&Array.isArray(a.coverage)&&a.coverage.some(row=>marked(row)&&valid(row.checked_at)&&Home.dates(String(row.day||'').slice(0,10),String(row.day||'').slice(0,10)).length===1);
 const timestamp=confirmed&&valid(a.generated_at)?a.generated_at:null;
 chip.textContent='Receita atualizada em '+(timestamp?crmWhen(timestamp):'—');
 chip.title=timestamp?'Último snapshot de atribuição concluído desta marca · '+timestamp:reason+' Indisponível desde '+crmWhen(new Date(now).toISOString())+'.';
 if(timestamp)chip.dataset.updatedAt=timestamp;else delete chip.dataset.updatedAt;
}

// Campanhas: O que vai sair, o que saiu e como foi? Públicos: Quem vou alcançar?
function crmIsTest(record){const d=record?.definition||record||{},names=[d.name,d.nome,d.subject];return names.some(v=>typeof v==='string'&&/^(?:\s*\[(?:QA(?:\s[^\]]*)?|TESTE|TEST)\]|\s*QA(?:\s|[-_:])|\s*Teste interno(?:\s|[-_:]|$))/i.test(v))||Array.isArray(d.tags)&&d.tags.some(t=>/^(?:qa(?:-native\d+)?|crm-internal-test|internal[-_]test|teste[-_]interno)$/i.test(t));}
function crmFreshness(value,now=Date.now()){const time=Date.parse(value),mins=Math.floor((now-time)/60000);return !Number.isFinite(time)||time>now?'Atualização indisponível':mins<1?'Atualizado agora':mins<60?'Atualizado há '+mins+' min':'Atualizado há '+Math.floor(mins/60)+' h';}
function crmShortWhen(value){return value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';}
function crmRuleSentence(rule,catalog,depth=0){if(!rule||depth>5)return 'Regras indisponíveis';const next=r=>crmRuleSentence(r,catalog,depth+1);if(rule.op==='confirmed')return next(rule.rule);if(['and','or'].includes(rule.op)&&Array.isArray(rule.rules))return (rule.op==='and'?'Todas as condições: ':'Qualquer condição: ')+rule.rules.map(next).join('; ');if(rule.op==='in_list'){const item=catalog?.lists?.find(l=>l.id===rule.list_id);return item?'Inscritos em '+item.name:'Inscritos na lista '+rule.list_id;}if(rule.op!=='condition')return 'Regras indisponíveis';const label={'purchase.count':'Pedidos','purchase.last_date':'Último pedido','purchase.amount':'Valor comprado','purchase.product':'Produto','relationship.rfm':'Perfil de relacionamento','signup.origin':'Origem da inscrição','signup.recorded_origin':'Formulário de inscrição','email.opened':'Abertura de e-mail','email.clicked':'Clique em e-mail'}[rule.field]||'Condição';const operator={eq:'igual a',gt:'maior que',gte:'a partir de',lt:'menor que',lte:'até',before:'antes de',on_or_before:'até',after:'depois de',on_or_after:'a partir de',purchased:'comprado',not_purchased:'não comprado',is:'igual a',is_not:'diferente de',within_last_days:'nos últimos',not_within_last_days:'não registrado nos últimos'}[rule.operator];if(!operator)return 'Regras indisponíveis';const product=rule.field==='purchase.product'?catalog?.products?.find(p=>p.id===rule.value):null;return label+' '+operator+' '+String(product?.name||rule.value)+(rule.operator?.includes('last_days')?' dias':'');}
function crmPrepareHeader(){const heading=document.querySelector('.workspace-heading'),top=document.querySelector('.workspace-topbar'),bar=document.querySelector('.crm-appbar'),brand=document.querySelector('.crm-store-switch'),channel=crmEl('crm-channel');if(!heading)return;heading.classList.add('crm-single-header');const toggle=bar?.querySelector('.navbar-toggler');if(toggle){toggle.classList.add('d-lg-none');heading.prepend(toggle);}if(brand)heading.prepend(brand);const title=crmEl('title');if(title){title.hidden=true;heading.append(title);}if(channel)heading.append(channel);top?.remove();bar?.remove();const actions=document.createElement('div');actions.id='crm-header-actions';actions.className='crm-header-actions';heading.append(actions);actions.append(crmEl('reload'));for(const id of ['new-campaign','new-audience']){const button=crmEl(id);if(button)actions.append(button);}const tests=crmEl('audience-show-tests');tests?.addEventListener('change',crmAudiences);crmCampaignFilters();crmInstallContextHeader(actions);}
